def main():
    texts = {fn: open(os.path.join(B, fn), encoding="utf-8").read() for fn in FILES + ["svglib.py"]}
    phase0(texts)
    print("phase 0 OK")
    for k, n in COUNTS.items():
        tot = sum(texts[fn].count(k) for fn in FILES)
        assert tot == n, f"COUNT MISMATCH {k!r}: got {tot}, expected {n}"
    print(f"phase 1 OK: {len(MAP)} keys, {sum(COUNTS.values())} occurrences")
    for fn in FILES:
        t = texts[fn]
        for k in sorted(MAP, key=len, reverse=True):
            t = t.replace(k, MAP[k])
        texts[fn] = t
    for fn in FILES:
        t = texts[fn]
        for k, v in MAP.items():
            if k != v:
                assert k not in t, f"RESIDUAL {k!r} in {fn}"
        assert "bridge" not in t and "\u6865\u63a5" not in t, f"FORBIDDEN residue in {fn}"
    for fn in FILES + ["svglib.py"]:
        open(os.path.join(B, fn), "w", encoding="utf-8").write(texts[fn])
    print("phase 2+3 OK: written, no residuals")

if __name__ == "__main__":
    main()
